struct VoxelTileRect {
    float u0, v0, u1, v1;
};

// One tile of the atlas as the corner UVs of its quad. The inset is half a texel:
// sampling exactly on the border is what makes the neighbour tile bleed into
// a face. quantum loads images unflipped and divides pixel-Y-from-the-top straight
// into v (MeshSystem::normalizeTileRect), so v = 0 is the atlas's first row: v0 is
// the tile's TOP edge and v1 its bottom edge, and a face must map its own up to v0.
inline VoxelTileRect voxelTileRect(int tile, float inset = 0.5f) {
    const float uv = 1.0f / 16.0f;
    const float per = uv / 16.0f;
    const float col = (float)(tile % 16);
    const float row = (float)(tile / 16);
    VoxelTileRect r;
    r.u0 = col * uv + per * inset;
    r.v0 = row * uv + per * inset;
    r.u1 = (col + 1.0f) * uv - per * inset;
    r.v1 = (row + 1.0f) * uv - per * inset;
    return r;
}

inline bool voxelTileIsCutout(int tile) {
    switch (tile) {
        case TILE_LEAVES_OAK: return true;
        case TILE_LEAVES_BIRCH: return true;
        case TILE_GLASS: return true;
        case TILE_FLOWER_POPPY: return true;
        case TILE_FLOWER_DANDELION: return true;
        case TILE_TALL_GRASS: return true;
        case TILE_DEAD_BUSH: return true;
        case TILE_TORCH: return true;
        default: return false;
    }
}

inline bool voxelTileIsLiquid(int tile) {
    switch (tile) {
        case TILE_WATER: return true;
        case TILE_LAVA: return true;
        default: return false;
    }
}

